/* A stable, resumable study day. Natural completion events drive each step. */
const foundationTotal=kanaRows.length*2+3;
const originalCleanState=cleanState;
cleanState=function(raw){const s=originalCleanState(raw),g=raw.guide||{};s.guide={foundation:num(g.foundation,foundationTotal),number:Math.max(1,num(g.number)),archive:[],day:null};
 s.guide.archive=(Array.isArray(g.archive)?g.archive:[]).filter(x=>x&&dateValid(x.date)).slice(-60).map(x=>({number:num(x.number),date:x.date,title:String(x.title||'').slice(0,120),writing:String(x.writing||'').slice(0,4000)}));
 const d=g.day;if(d&&dateValid(d.date)&&LEVELS.includes(d.level)&&Array.isArray(d.steps)&&d.steps.length>0&&d.steps.length<=6&&d.steps.every(t=>t&&['kana','recall','grammar','vocab','reading','listening','practice','course'].includes(t.kind)&&Array.isArray(t.ids)&&t.ids.length<=20&&t.ids.every(id=>validGrammar.has(id)||validWords.has(id)||validTexts.has(id))))s.guide.day={date:d.date,number:Math.max(1,num(d.number)),level:d.level,foundation:num(d.foundation,foundationTotal),steps:d.steps.map(t=>({kind:t.kind,ids:t.ids,done:!!t.done,doneIds:(Array.isArray(t.doneIds)?t.doneIds:[]).filter(id=>t.ids.includes(id))})),writing:String(d.writing||'').slice(0,4000)};return s;};
try{const saved=JSON.parse(localStorage.getItem('hajime-study-v2')||'null');state=cleanState({...state,guide:saved?.guide});}catch{state=cleanState(state);}
let guideActive=false,recallShown=false;
function foundationLesson(n){if(n<kanaRows.length*2){const mode=n<kanaRows.length?0:1,r=kanaRows[n%kanaRows.length];return{title:`${mode?'片假名':'平假名'} · ${r[mode].replaceAll(' ','')}`,chars:Array.from(r[mode]).map((char,i)=>({char,romaji:r[2][i]})).filter(x=>x.char!==' '),note:'先看字形，按罗马音尝试发音；点读后跟读三遍。再盖住提示，试着认读并在纸上写一遍。'};}
 if(n===kanaRows.length*2)return{title:'浊音与半浊音',chars:voicedRows.flatMap(r=>Array.from(r[0]).map((char,i)=>({char,romaji:r[2][i]}))),note:'清音加「゛」成为浊音；は行加「゜」成为半浊音。可分几组反复认读。'};
 if(n===kanaRows.length*2+1)return{title:'拗音：小ゃ・ゅ・ょ',chars:contracted.slice(0,5).flatMap(r=>r[2].map((romaji,i)=>({char:r[0].slice(i*2,i*2+2),romaji}))),note:'きゃ、しゅ、ちょ等各占一拍。注意小ゃ和普通や的区别。其余拗音可以在五十音页继续巩固。'};
 return{title:'长音、促音与拨音',chars:[{char:'おばさん',romaji:'obasan · 阿姨'},{char:'おばあさん',romaji:'obaasan · 奶奶'},{char:'きって',romaji:'kitte · 邮票'},{char:'きいて',romaji:'kiite · 请听'},{char:'ほん',romaji:'hon · 书'}],note:'长音延长一拍；小っ停顿一拍；ん也占一拍。跟读后比较每一组的拍数。'};}
function archiveDay(){const g=state.guide,d=g.day;if(d){g.archive.push({number:d.number,date:d.date,title:d.level==='N5'&&d.foundation<foundationTotal?foundationLesson(d.foundation).title:`${d.level} · 语法与应用`,writing:d.writing});g.archive=g.archive.slice(-60);g.number=d.number+1;}g.day=null;}
function makeStudyDay(){const g=state.guide;const stages=LEVELS.slice(LEVELS.indexOf(state.plan.start),LEVELS.indexOf(state.plan.target)+1);const l=stages.find(x=>{const c=counts(x),exam=[...state.history].reverse().find(h=>h.level===x);return c.g<c.gt||c.w/c.wt<.7||c.r<c.rt||c.l<c.lt||(exam?.score||0)<80;})||stages.at(-1)||'N5';let steps;
 if(l==='N5'&&g.foundation<foundationTotal)steps=[{kind:'kana',ids:[],done:false},{kind:'recall',ids:[],done:false}];
 else {const lesson=nextGrammar(l),w=lw(l),amount=state.plan.minutes===20?5:state.plan.minutes===40?8:10;const ordered=[...w.filter(x=>state.wordReviews[x.id]&&state.wordReviews[x.id].due<=dateKey()),...w.filter(x=>!state.wordReviews[x.id]),...w.filter(x=>state.wordReviews[x.id]?.due>dateKey())];const wordIds=ordered.slice(0,amount).map(x=>x.id);steps=[{kind:'grammar',ids:[lesson.id],done:false},{kind:'vocab',ids:wordIds,done:false}];
 if(l!=='N5'||counts(l).g>=4){for(const [kind,list]of [['reading',lr(l)],['listening',ll(l)]]){if(state.plan.minutes===20&&kind!==(g.number%2?'reading':'listening'))continue;const t=list.find(x=>!state.textDone.includes(x.id))||list[g.number%list.length];if(t)steps.push({kind,ids:[t.id],done:false});}}
 steps.push({kind:'practice',ids:[lesson.id,...lg(l).filter(x=>state.completed.includes(x.id)&&x.id!==lesson.id).slice(-2).map(x=>x.id),...wordIds.slice(0,2)],done:false});}
 g.day={date:dateKey(),number:g.number,level:l,foundation:g.foundation,steps,writing:''};persist();return g.day;}
function studyDay(){const g=state.guide;if(g.day&&g.day.date!==dateKey()&&g.day.steps.every(x=>x.done))archiveDay();return g.day||makeStudyDay();}
function syncStudyDay(){const d=studyDay();for(const t of d.steps){if(t.done)continue;if(t.kind==='grammar')t.done=t.ids.every(x=>state.completed.includes(x));if(t.kind==='vocab')t.done=t.ids.every(x=>(t.doneIds||[]).includes(x));}persist();return d;}
function currentStep(){return syncStudyDay().steps.find(x=>!x.done);}
function guidedWords(){const d=state.guide?.day,t=d?.steps.find(x=>x.kind==='vocab');return guideActive&&page==='vocab'&&t?t.ids.map(id=>words.find(w=>w.id===id)).filter(Boolean):null;}
function stepInfo(t,d){if(t.kind==='kana'||t.kind==='recall')return{title:t.kind==='kana'?`认读 ${foundationLesson(d.foundation).title}`:'盖住提示，认读与书写',desc:t.kind==='kana'?'一小组假名，跟读三遍，观察字形。':'不用罗马音认读；在纸上写一遍，再对照字形。',time:t.kind==='kana'?'10 分钟':'5–10 分钟'};
 if(t.kind==='grammar'){const q=questionById(t.ids[0]);return{title:q.title,desc:'读中文规则 → 跟读例句 → 完成课内题 → 标记已学。',time:'10–15 分钟'};}
 return{title:{vocab:`认读与复习 ${t.ids.length} 张词卡`,reading:questionById(t.ids[0])?.title,listening:questionById(t.ids[0])?.title,practice:`巩固今天所学 · ${t.ids.length} 题`}[t.kind],desc:{vocab:'先回忆，再翻卡；「还不熟」也会记录本次复习。',reading:'阅读短文，作答后看解析，再记录完成。',listening:'先听后答，再展开原文精听；未安装日语语音时可先看原文。',practice:'只练今天的句型、已学语法与本组词汇。'}[t.kind],time:{vocab:'5–10 分钟',reading:'5 分钟',listening:'5 分钟',practice:'3–5 分钟'}[t.kind]};}
function writingPanel(d){const t=d.steps.find(x=>x.kind==='grammar'),q=t&&questionById(t.ids[0]);return `<details class="writing-panel"><summary>✎ 可选写作训练 <span>不影响必修完成</span></summary><p>${q?`用今天的「${esc(q.title)}」写 2–3 句与你自己有关的话。先替换例句中的人物、物品或地点。`:'先练习书写今天的假名。能写单词后，可以尝试一句简单自我介绍。'}</p><label for="writingDraft">我的日语草稿</label><textarea id="writingDraft" maxlength="4000" placeholder="在这里写下你的日语，可以随时保存…">${esc(d.writing)}</textarea><div class="toolbar"><button class="primary" id="saveWriting">保存草稿 ✓</button><span id="writingSaved" role="status"></span></div><details><summary>查看参考表达与自查清单</summary><p lang="ja">${q?esc(q.examples[0][0]):'わたしは学生です。'}</p><p>① 是否用了今天的句型？ ② 助词、词尾和假名是否正确？ ③ 用自己的信息替换后，意思是否连贯？</p><small>参考表达用于对照；本站暂不自动批改或评分。</small></details></details>`;}
renderPlan=function(){const d=syncStudyDay(),active=d.steps.findIndex(x=>!x.done),done=d.steps.filter(x=>x.done).length,all=active<0,foundation=d.level==='N5'&&d.foundation<foundationTotal;
return title('YOUR NEXT STEP','今日学习 · 一步一步来','按顺序完成，随时继续。')+`<section class="container page-section"><div class="study-dashboard"><div><span class="label">第 ${d.number} 个学习日 · ${d.level}${foundation?' 前置入门':''}</span><h2>${all?'今天的必修任务完成了 ✓':foundation?foundationLesson(d.foundation).title:stepInfo(d.steps[active],d).title}</h2><p>${all?'可以休息，或开始下一学习日。':`现在做第 ${active+1} 步：${stepInfo(d.steps[active],d).desc}`}</p><div class="study-meter"><div style="width:${done/d.steps.length*100}%"></div></div><small>必修 ${done} / ${d.steps.length} · 建议预算 ${state.plan.minutes} 分钟${d.date!==dateKey()?' · 继续上次未完成的计划':''}</small></div><div class="study-action">${all?'<button class="primary" id="nextStudyDay">开始下一学习日 →</button><small>进度已保存</small>':'<button class="primary" id="startStudyStep">'+(done?'继续下一步 →':'开始今天的学习 →')+'</button><small>完成后回到这里继续</small>'}</div></div><div class="beginner-route" aria-label="学习顺序">${[['01','假名与发音'],['02','基础句型 + 词汇'],['03','阅读 + 听力'],['04','复习 + 测评']].map(([n,s],i)=>`<div class="${i===(foundation?0:counts(d.level).g<4?1:2)?'current':''}"><b>${n}</b><span>${s}</span></div>`).join('')}</div><p class="completion-note">${foundation?`先完成 ${foundationTotal} 组假名与发音练习（已完成 ${state.guide.foundation} 组），再进入 N5 单元课程。可以反复复习，不必追求一天背完。 <button class="more" id="skipFoundation">我已掌握五十音，进入 N5 单元课程 →</button>`:d.level==='N5'&&counts('N5').g<4?'先学习前四课的基础判断句、指示词和助词；之后加入阅读与听力，避免一开始就面对整篇日文。':'按本站课程顺序推进；阅读听力与句型结合，阶段末用测评检查薄弱项。'}</p><div class="guided-steps">${d.steps.map((t,i)=>{const info=stepInfo(t,d);return `<article class="guided-step ${t.done?'done':i===active?'current':'pending'}"><span class="step-number">${t.done?'✓':String(i+1).padStart(2,'0')}</span><div><span class="step-state">${t.done?'已完成':i===active?'当前任务':'待学习'} · ${info.time}</span><h3>${esc(info.title)}</h3><p>${info.desc}</p></div><button class="${i===active?'primary':'secondary'}" data-guidestep="${i}" ${i>active&&!all?'disabled':''}>${t.done?'再复习':i===active?'开始 →':'等待前一步'}</button></article>`;}).join('')}</div><div id="foundationWorkspace"></div>${writingPanel(d)}${!foundation&&counts(d.level).g===counts(d.level).gt?`<div class="exam-banner"><div><span class="label">阶段检查</span><h2>${d.level} 语法已学完，检查能否熟练运用</h2><p>继续巩固词汇与篇章，完成阶段测评后，再按学习进度进入下一等级。</p></div><button class="primary" id="planExam">开始阶段测评 →</button></div>`:''}<details class="plan-options"><summary>调整起点、目标与每日时间</summary><form id="planForm" class="plan-settings"><label>开始阶段<select name="start">${LEVELS.map(l=>`<option ${l===state.plan.start?'selected':''}>${l}</option>`).join('')}</select></label><label>目标等级<select name="target">${LEVELS.map(l=>`<option ${l===state.plan.target?'selected':''}>${l}</option>`).join('')}</select></label><label>每天时间<select name="minutes">${[20,40,60].map(n=>`<option value="${n}" ${n===state.plan.minutes?'selected':''}>${n} 分钟</option>`).join('')}</select></label><button class="primary">保存计划 ✓</button></form><p>当前学习日保留；新设置从下一学习日生效。日期变化后，未完成的任务会继续保留。</p></details>${state.guide.archive.length?`<details class="plan-options"><summary>已完成学习日 · ${state.guide.archive.length} 条近期记录</summary>${[...state.guide.archive].reverse().map(x=>`<article class="study-history"><b>第 ${x.number} 学习日 · ${x.date}</b><p>${esc(x.title)}</p>${x.writing?`<p lang="ja">${esc(x.writing).replaceAll('\n','<br>')}</p>`:''}</article>`).join('')}</details>`:''}<div class="hint">任务量是建议；完成记录表示已练习，不代表已经掌握。完整 N5–N2 备考仍需扩大词汇与篇章练习。<button class="more" data-page="progress">查看阶段进度与测评记录 →</button></div></section>`;};
function showFoundation(t){const d=studyDay(),f=foundationLesson(d.foundation),recall=t.kind==='recall';$('#foundationWorkspace').innerHTML=`<div class="foundation-workspace"><span class="label">${recall?'先回忆，再核对':'听 · 读 · 写'}</span><h2>${f.title}</h2><p>${f.note}</p><div class="guided-kana">${f.chars.map(x=>`<button data-speak="${esc(x.char)}"><b lang="ja">${x.char}</b><small class="${recall&&!recallShown?'':'romaji'}">${recall&&!recallShown?'先自己读':x.romaji}</small></button>`).join('')}</div>${recall?'<button class="secondary" id="showRecall">'+(recallShown?'再次盖住提示':'显示读音，核对答案')+'</button>':''}<p class="completion-note">${recall?'先认读，再在纸上写一遍。仍不熟悉就继续练习；确认能认读后再完成本步。':'点读需要系统日语语音。没有语音时可按罗马音练习，并在五十音页查看发音规则。'}</p><button class="primary" id="finishFoundation">${recall?'我已完成认读与书写 ✓':'跟读完成，进入回忆练习 →'}</button></div>`;$('#foundationWorkspace').scrollIntoView({behavior:'smooth',block:'start'});}
function runStep(i){const d=studyDay(),t=d.steps[i];if(!t)return;guideActive=true;recallShown=false;if(['kana','recall'].includes(t.kind)){showFoundation(t);return;}if(t.kind==='grammar'){if(page!=='plan')go('plan',d.level);openLesson(t.ids[0]);const next=$('#lessonBody [data-nextlesson]');if(next)next.hidden=true;$('#lessonBody [data-complete]').textContent='完成本课，返回今日计划 ✓';return;}if(t.kind==='practice'){if(state.activeQuiz){go('practice',state.activeQuiz.level);toast('先完成或结束当前练习，再开始今日巩固。');return;}state.activeQuiz={level:d.level,mode:'grammar',ids:t.ids,answers:[],index:0};persist();go('practice',d.level);return;}go(t.kind,d.level);}
const originalRender=render;
render=function(scroll=true){originalRender(scroll);updateGuideRibbon();};
function updateGuideRibbon(){document.querySelector('.guide-ribbon')?.remove();if(!guideActive||page==='plan')return;const d=syncStudyDay(),t=d.steps.find(x=>!x.done),next=t?stepInfo(t,d).title:'今天的必修已完成';const ribbon=document.createElement('div');ribbon.className='guide-ribbon';ribbon.innerHTML=`<div class="container"><div><strong>第 ${d.number} 学习日 · ${d.steps.filter(x=>x.done).length} / ${d.steps.length} 完成</strong><small>${esc(next)}</small></div><button class="primary" data-page="plan">返回今日计划 →</button><button class="more" id="leaveGuided">自由学习</button></div>`;$('#view').prepend(ribbon);if((page==='reading'||page==='listening')&&t?.kind===page){document.querySelectorAll('.text-card').forEach(el=>{el.hidden=el.querySelector('[data-textdone]')?.dataset.textdone!==t.ids[0];});}}
const originalFinishQuiz=finishQuiz;
finishQuiz=function(){const q=state.activeQuiz,d=state.guide.day,t=d?.steps.find(x=>x.kind==='practice');if(q&&t&&q.level===d.level&&q.ids.join('|')===t.ids.join('|')&&q.answers.length===q.ids.length)t.done=true;originalFinishQuiz();updateGuideRibbon();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.wordrate!==undefined&&guideActive){const t=state.guide.day?.steps.find(x=>x.kind==='vocab');if(t?.ids.includes(b.dataset.word)){t.doneIds=[...new Set([...(t.doneIds||[]),b.dataset.word])];persist();updateGuideRibbon();}}
 if(b.id==='startStudyStep'||b.dataset.guidestep!==undefined){const d=syncStudyDay(),i=b.dataset.guidestep!==undefined?Number(b.dataset.guidestep):d.steps.findIndex(x=>!x.done);runStep(i);}
 if(b.id==='finishFoundation'){const d=studyDay(),t=d.steps.find(x=>!x.done);if(t&&['kana','recall'].includes(t.kind)){t.done=true;touch();if(t.kind==='recall')state.guide.foundation=Math.max(state.guide.foundation,d.foundation+1);persist();render(false);if(t.kind==='kana')runStep(1);}}
 if(b.id==='showRecall'){recallShown=!recallShown;showFoundation(studyDay().steps[1]);}
 if(b.id==='skipFoundation'){state.guide.foundation=foundationTotal;state.guide.day=null;persist();render(false);toast('已进入语法学习；五十音仍可随时复习。');}
 if(b.id==='nextStudyDay'){const d=syncStudyDay();if(d.steps.every(x=>x.done)){archiveDay();guideActive=false;persist();render(false);toast('下一学习日已准备好。');}}
 if(b.id==='saveWriting'){studyDay().writing=$('#writingDraft').value;persist();$('#writingSaved').textContent='草稿已保存';}
 if(b.id==='planExam'){guideActive=false;go('practice',studyDay().level);if(!state.activeQuiz)startQuiz('exam');}
 if(b.id==='leaveGuided'){guideActive=false;render(false);}
 if(b.dataset.textdone&&!b.disabled)return;
 if(b.dataset.textdone){const d=state.guide.day,t=d?.steps.find(x=>x.ids.includes(b.dataset.textdone)&&x.kind===page);if(guideActive&&t){t.done=true;persist();updateGuideRibbon();}}
});
document.addEventListener('input',e=>{if(e.target.id==='writingDraft'){studyDay().writing=e.target.value;persist();$('#writingSaved').textContent='草稿已自动保存';}});
// Make the primary homepage entry follow the guided path, while preserving free navigation.
const originalHome=renderHome;
renderHome=function(){return originalHome().replace(`data-page="lessons">${level} 开始学习`,`data-page="plan">开始今日学习`).replace('安排我的学习','调整学习计划');};
render(false);
